n=30
g=[[0]*n for _ in range(n)]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts=[1,8,15,22,29]
for i,r0 in enumerate(starts):
 for j,c0 in enumerate(starts):
  for dr in range(5):
   for dc in range(5):
    r,c=r0+dr,c0+dc
    if r<n and c<n:
     g[r][c]=4
  if i<4 and j<4:
   for r in range(r0+1,r0+4):
    for c in range(c0+1,c0+4): g[r][c]=colors[i][j]
# draw color 3: horizontal between tile columns 0 and 3 on tile rows 0 and 2
for ti in [0,2]:
 r0=starts[ti]
 for r in range(r0+1,r0+4):
  for tj in [0,1,2]:
   # inter-tile background gap after each 5-wide object
   cgap=starts[tj]+5
   for c in range(cgap,cgap+2): g[r][c]=3
# vertical between tile rows 0 and 2 along tile cols 0 and 3
for tj in [0,3]:
 c0=starts[tj]
 for c in range(c0+1,c0+4):
  for ti in [0,1]:
   rgap=starts[ti]+5
   for r in range(rgap,rgap+2): g[r][c]=3
# color 8: horizontal between tile cols 1 and 2, tile rows 1 and 3
for ti in [1,3]:
 r0=starts[ti]
 for r in range(r0+1,r0+4):
  cgap=starts[1]+5
  for c in range(cgap,cgap+2): g[r][c]=8
# vertical between tile rows 1 and 3 in tile cols 1 and 2
for tj in [1,2]:
 c0=starts[tj]
 for c in range(c0+1,c0+4):
  for ti in [1,2]:
   rgap=starts[ti]+5
   for r in range(rgap,rgap+2): g[r][c]=8
print('\n'.join(' '.join(map(str,row)) for row in g))
